"""
Port interfaces (abstract contracts) for all infrastructure adapters.

Every concrete adapter — regardless of profile — implements exactly
these interfaces.  Business logic depends only on these ports.
"""

from __future__ import annotations

import abc
from typing import Any, Dict, Optional


class ObjectStoragePort(abc.ABC):
    """Put / get / delete binary objects in a bucket-like namespace."""

    @abc.abstractmethod
    def put_object(self, bucket: str, key: str, data: bytes, metadata: Optional[Dict[str, str]] = None) -> None:
        """Store *data* under *bucket*/*key*."""

    @abc.abstractmethod
    def get_object(self, bucket: str, key: str) -> bytes:
        """Return the raw bytes previously stored under *bucket*/*key*.

        Raises ``KeyError`` when the object does not exist.
        """

    @abc.abstractmethod
    def delete_object(self, bucket: str, key: str) -> None:
        """Delete the object.  Idempotent — no error if missing."""

    @abc.abstractmethod
    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        """Return keys matching *prefix* inside *bucket*."""


class QueuePort(abc.ABC):
    """Simple message-queue send / receive contract."""

    @abc.abstractmethod
    def send_message(self, queue_name: str, body: str, attributes: Optional[Dict[str, str]] = None) -> str:
        """Enqueue a message.  Return a message-id."""

    @abc.abstractmethod
    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[Dict[str, Any]]:
        """Receive up to *max_messages*.  Each dict has at least ``message_id``, ``body``, ``receipt_handle``."""

    @abc.abstractmethod
    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        """Acknowledge / delete a received message."""


class EventingPort(abc.ABC):
    """Publish domain events to a topic / bus."""

    @abc.abstractmethod
    def publish(self, topic: str, event_type: str, payload: Dict[str, Any]) -> str:
        """Publish an event.  Return an event-id or message-id."""


class SecretsPort(abc.ABC):
    """Read-only access to secret values."""

    @abc.abstractmethod
    def get_secret(self, secret_name: str) -> str:
        """Return the current plaintext value of *secret_name*.

        Raises ``KeyError`` when the secret does not exist.
        """

    @abc.abstractmethod
    def get_secret_json(self, secret_name: str) -> Dict[str, Any]:
        """Return the secret parsed as JSON dict.

        Raises ``KeyError`` when the secret does not exist.
        Raises ``ValueError`` when the value is not valid JSON.
        """


class LogSinkPort(abc.ABC):
    """Structured log sink for audit / operational events."""

    @abc.abstractmethod
    def emit(self, log_entry: Dict[str, Any]) -> None:
        """Write one structured log entry to the configured sink."""

"""
AdapterRegistry — profile-aware adapter factory.

Reads ``DEPLOYMENT_PROFILE`` from the environment (default ``onprem``),
validates it, and lazily provides concrete adapter instances for every
canonical slot.

Business code never imports concrete adapters directly; it calls::

    registry = get_registry()
    storage  = registry.object_storage()
"""

from __future__ import annotations

import os
from functools import lru_cache
from typing import Optional

from shared.adapters.adapter_contract import (
    ADAPTER_SLOTS,
    validate_profile,
    validate_registry_parity,
)
from shared.adapters.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)


class AdapterRegistry:
    """Lazy, profile-selected adapter factory.

    Parameters
    ----------
    profile:
        ``"aws"`` or ``"onprem"``.  When *None*, reads
        ``DEPLOYMENT_PROFILE`` from the environment (default ``"onprem"``).
    """

    def __init__(self, profile: Optional[str] = None) -> None:
        raw = profile or os.environ.get("DEPLOYMENT_PROFILE", "onprem")
        self._profile: str = validate_profile(raw)

    @property
    def profile(self) -> str:
        return self._profile

    # ── Slot factories ──────────────────────────────────────────────

    def object_storage(self) -> ObjectStoragePort:
        if self._profile == "aws":
            from shared.adapters.aws.s3_storage import S3ObjectStorage
            return S3ObjectStorage()
        from shared.adapters.onprem.minio_storage import MinioObjectStorage
        return MinioObjectStorage()

    def queue(self) -> QueuePort:
        if self._profile == "aws":
            from shared.adapters.aws.sqs_queue import SqsQueue
            return SqsQueue()
        from shared.adapters.onprem.redis_queue import RedisQueue
        return RedisQueue()

    def eventing(self) -> EventingPort:
        if self._profile == "aws":
            from shared.adapters.aws.sns_eventing import SnsEventing
            return SnsEventing()
        from shared.adapters.onprem.nats_eventing import NatsEventing
        return NatsEventing()

    def secrets(self) -> SecretsPort:
        if self._profile == "aws":
            from shared.adapters.aws.ssm_secrets import SsmSecrets
            return SsmSecrets()
        from shared.adapters.onprem.vault_secrets import VaultSecrets
        return VaultSecrets()

    def log_sink(self) -> LogSinkPort:
        if self._profile == "aws":
            from shared.adapters.aws.cloudwatch_log_sink import CloudWatchLogSink
            return CloudWatchLogSink()
        from shared.adapters.onprem.file_log_sink import FileLogSink
        return FileLogSink()

    # ── Self-check ──────────────────────────────────────────────────

    def validate(self) -> None:
        """Run parity validation on this registry instance."""
        validate_registry_parity(self)


@lru_cache(maxsize=1)
def get_registry() -> AdapterRegistry:
    """Module-level singleton, cached on first call.

    To reset (e.g. in tests), call ``get_registry.cache_clear()``.
    """
    return AdapterRegistry()

"""
AWS S3 ObjectStoragePort adapter.

Uses boto3 with endpoint_url override support for LocalStack.
"""

from __future__ import annotations

import os
from typing import Dict, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import ObjectStoragePort


class S3ObjectStorage(ObjectStoragePort):
    """Concrete S3-backed object storage."""

    def __init__(self) -> None:
        endpoint_url = os.environ.get("AWS_ENDPOINT_URL") or os.environ.get("S3_ENDPOINT_URL")
        kwargs: Dict[str, str] = {}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url

        region = os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self._client = boto3.client("s3", region_name=region, **kwargs)  # type: ignore[arg-type]

    # ── Port implementation ─────────────────────────────────────────

    def put_object(self, bucket: str, key: str, data: bytes, metadata: Optional[Dict[str, str]] = None) -> None:
        extra: Dict[str, object] = {}
        if metadata:
            extra["Metadata"] = metadata
        self._ensure_bucket(bucket)
        self._client.put_object(Bucket=bucket, Key=key, Body=data, **extra)

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            resp = self._client.get_object(Bucket=bucket, Key=key)
            return resp["Body"].read()  # type: ignore[no-any-return]
        except ClientError as exc:
            if exc.response["Error"]["Code"] in ("NoSuchKey", "404"):
                raise KeyError(f"{bucket}/{key}") from exc
            raise

    def delete_object(self, bucket: str, key: str) -> None:
        try:
            self._client.delete_object(Bucket=bucket, Key=key)
        except ClientError:
            pass  # idempotent

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        try:
            resp = self._client.list_objects_v2(Bucket=bucket, Prefix=prefix)
            return [obj["Key"] for obj in resp.get("Contents", [])]
        except ClientError:
            return []

    # ── Helpers ─────────────────────────────────────────────────────

    def _ensure_bucket(self, bucket: str) -> None:
        """Create bucket if it does not exist (useful for LocalStack)."""
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError:
            try:
                self._client.create_bucket(Bucket=bucket)
            except ClientError:
                pass  # race or already exists

"""
AWS SQS QueuePort adapter.
"""

from __future__ import annotations

import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import QueuePort


class SqsQueue(QueuePort):
    """Concrete SQS-backed queue."""

    def __init__(self) -> None:
        endpoint_url = os.environ.get("AWS_ENDPOINT_URL") or os.environ.get("SQS_ENDPOINT_URL")
        kwargs: Dict[str, str] = {}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        region = os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self._client = boto3.client("sqs", region_name=region, **kwargs)  # type: ignore[arg-type]
        self._url_cache: Dict[str, str] = {}

    def _queue_url(self, queue_name: str) -> str:
        if queue_name not in self._url_cache:
            try:
                resp = self._client.get_queue_url(QueueName=queue_name)
                self._url_cache[queue_name] = resp["QueueUrl"]
            except ClientError:
                resp = self._client.create_queue(QueueName=queue_name)
                self._url_cache[queue_name] = resp["QueueUrl"]
        return self._url_cache[queue_name]

    def send_message(self, queue_name: str, body: str, attributes: Optional[Dict[str, str]] = None) -> str:
        msg_attrs: Dict[str, Any] = {}
        if attributes:
            msg_attrs = {
                k: {"StringValue": v, "DataType": "String"} for k, v in attributes.items()
            }
        resp = self._client.send_message(
            QueueUrl=self._queue_url(queue_name),
            MessageBody=body,
            MessageAttributes=msg_attrs,
        )
        return resp["MessageId"]

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[Dict[str, Any]]:
        resp = self._client.receive_message(
            QueueUrl=self._queue_url(queue_name),
            MaxNumberOfMessages=min(max_messages, 10),
            WaitTimeSeconds=wait_seconds,
        )
        results: list[Dict[str, Any]] = []
        for msg in resp.get("Messages", []):
            results.append({
                "message_id": msg["MessageId"],
                "body": msg["Body"],
                "receipt_handle": msg["ReceiptHandle"],
            })
        return results

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        self._client.delete_message(
            QueueUrl=self._queue_url(queue_name),
            ReceiptHandle=receipt_handle,
        )

"""
AWS SNS EventingPort adapter.
"""

from __future__ import annotations

import json
import os
from typing import Any, Dict

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import EventingPort


class SnsEventing(EventingPort):
    """Concrete SNS-backed eventing."""

    def __init__(self) -> None:
        endpoint_url = os.environ.get("AWS_ENDPOINT_URL") or os.environ.get("SNS_ENDPOINT_URL")
        kwargs: Dict[str, str] = {}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        region = os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self._client = boto3.client("sns", region_name=region, **kwargs)  # type: ignore[arg-type]
        self._arn_cache: Dict[str, str] = {}

    def _topic_arn(self, topic: str) -> str:
        if topic not in self._arn_cache:
            try:
                resp = self._client.create_topic(Name=topic)
                self._arn_cache[topic] = resp["TopicArn"]
            except ClientError:
                # list and find
                resp = self._client.list_topics()
                for t in resp.get("Topics", []):
                    if t["TopicArn"].endswith(f":{topic}"):
                        self._arn_cache[topic] = t["TopicArn"]
                        break
                else:
                    raise
        return self._arn_cache[topic]

    def publish(self, topic: str, event_type: str, payload: Dict[str, Any]) -> str:
        message = json.dumps({"event_type": event_type, "payload": payload})
        resp = self._client.publish(
            TopicArn=self._topic_arn(topic),
            Message=message,
            Subject=event_type,
        )
        return resp["MessageId"]

"""
AWS SSM Parameter Store SecretsPort adapter.
"""

from __future__ import annotations

import json
import os
from typing import Any, Dict

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import SecretsPort


class SsmSecrets(SecretsPort):
    """Concrete SSM Parameter Store secrets reader."""

    def __init__(self) -> None:
        endpoint_url = os.environ.get("AWS_ENDPOINT_URL") or os.environ.get("SSM_ENDPOINT_URL")
        kwargs: Dict[str, str] = {}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        region = os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self._client = boto3.client("ssm", region_name=region, **kwargs)  # type: ignore[arg-type]

    def get_secret(self, secret_name: str) -> str:
        try:
            resp = self._client.get_parameter(Name=secret_name, WithDecryption=True)
            return resp["Parameter"]["Value"]  # type: ignore[no-any-return]
        except ClientError as exc:
            if exc.response["Error"]["Code"] == "ParameterNotFound":
                raise KeyError(secret_name) from exc
            raise

    def get_secret_json(self, secret_name: str) -> Dict[str, Any]:
        raw = self.get_secret(secret_name)
        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Secret {secret_name!r} is not valid JSON") from exc
        if not isinstance(parsed, dict):
            raise ValueError(f"Secret {secret_name!r} JSON is not a dict")
        return parsed

"""
AWS CloudWatch Logs LogSinkPort adapter.
"""

from __future__ import annotations

import json
import os
import time
from typing import Any, Dict

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import LogSinkPort


class CloudWatchLogSink(LogSinkPort):
    """Concrete CloudWatch Logs sink."""

    def __init__(self) -> None:
        endpoint_url = os.environ.get("AWS_ENDPOINT_URL") or os.environ.get("LOGS_ENDPOINT_URL")
        kwargs: Dict[str, str] = {}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        region = os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
        self._client = boto3.client("logs", region_name=region, **kwargs)  # type: ignore[arg-type]
        self._log_group = os.environ.get("LOG_GROUP_NAME", "/app/default")
        self._log_stream = os.environ.get("LOG_STREAM_NAME", "default-stream")
        self._sequence_token: str | None = None
        self._ensure_log_group()

    def _ensure_log_group(self) -> None:
        try:
            self._client.create_log_group(logGroupName=self._log_group)
        except ClientError:
            pass
        try:
            self._client.create_log_stream(
                logGroupName=self._log_group,
                logStreamName=self._log_stream,
            )
        except ClientError:
            pass

    def emit(self, log_entry: Dict[str, Any]) -> None:
        event = {
            "timestamp": int(time.time() * 1000),
            "message": json.dumps(log_entry),
        }
        kwargs: Dict[str, Any] = {
            "logGroupName": self._log_group,
            "logStreamName": self._log_stream,
            "logEvents": [event],
        }
        if self._sequence_token:
            kwargs["sequenceToken"] = self._sequence_token
        try:
            resp = self._client.put_log_events(**kwargs)
            self._sequence_token = resp.get("nextSequenceToken")
        except ClientError:
            # Best-effort; do not crash the caller
            pass

"""
On-prem MinIO ObjectStoragePort adapter.

Uses boto3 S3-compatible API pointed at a MinIO endpoint.
"""

from __future__ import annotations

import os
from typing import Dict, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import ObjectStoragePort


class MinioObjectStorage(ObjectStoragePort):
    """Concrete MinIO-backed object storage (S3-compatible)."""

    def __init__(self) -> None:
        endpoint_url = os.environ.get("MINIO_ENDPOINT_URL", "http://localhost:9000")
        access_key = os.environ.get("MINIO_ACCESS_KEY", os.environ.get("AWS_ACCESS_KEY_ID", "minioadmin"))
        secret_key = os.environ.get("MINIO_SECRET_KEY", os.environ.get("AWS_SECRET_ACCESS_KEY", "minioadmin"))
        region = os.environ.get("MINIO_REGION", "us-east-1")

        self._client = boto3.client(
            "s3",
            endpoint_url=endpoint_url,
            aws_access_key_id=access_key,
            aws_secret_access_key=secret_key,
            region_name=region,
        )

    def put_object(self, bucket: str, key: str, data: bytes, metadata: Optional[Dict[str, str]] = None) -> None:
        extra: Dict[str, object] = {}
        if metadata:
            extra["Metadata"] = metadata
        self._ensure_bucket(bucket)
        self._client.put_object(Bucket=bucket, Key=key, Body=data, **extra)

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            resp = self._client.get_object(Bucket=bucket, Key=key)
            return resp["Body"].read()  # type: ignore[no-any-return]
        except ClientError as exc:
            if exc.response["Error"]["Code"] in ("NoSuchKey", "404"):
                raise KeyError(f"{bucket}/{key}") from exc
            raise

    def delete_object(self, bucket: str, key: str) -> None:
        try:
            self._client.delete_object(Bucket=bucket, Key=key)
        except ClientError:
            pass

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        try:
            resp = self._client.list_objects_v2(Bucket=bucket, Prefix=prefix)
            return [obj["Key"] for obj in resp.get("Contents", [])]
        except ClientError:
            return []

    def _ensure_bucket(self, bucket: str) -> None:
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError:
            try:
                self._client.create_bucket(Bucket=bucket)
            except ClientError:
                pass

"""
On-prem HashiCorp Vault SecretsPort adapter.

Uses hvac client library.
"""

from __future__ import annotations

import json
import os
from typing import Any, Dict

from shared.adapters.ports import SecretsPort


class VaultSecrets(SecretsPort):
    """Concrete Vault KV v2 secrets reader."""

    def __init__(self) -> None:
        import hvac

        vault_addr = os.environ.get("VAULT_ADDR", "http://localhost:8200")
        vault_token = os.environ.get("VAULT_TOKEN", "root")
        self._mount = os.environ.get("VAULT_MOUNT", "secret")
        self._client = hvac.Client(url=vault_addr, token=vault_token)

    def get_secret(self, secret_name: str) -> str:
        try:
            resp = self._client.secrets.kv.v2.read_secret_version(
                path=secret_name,
                mount_point=self._mount,
            )
            data = resp["data"]["data"]
            # Convention: if the secret has a single key "value", return it directly
            if "value" in data:
                return str(data["value"])
            return json.dumps(data)
        except Exception as exc:
            raise KeyError(secret_name) from exc

    def get_secret_json(self, secret_name: str) -> Dict[str, Any]:
        raw = self.get_secret(secret_name)
        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Secret {secret_name!r} is not valid JSON") from exc
        if not isinstance(parsed, dict):
            raise ValueError(f"Secret {secret_name!r} JSON is not a dict")
        return parsed

