"""
Adapter contract validation and profile constants.

This module defines:
* the canonical set of DEPLOYMENT_PROFILE values
* the canonical set of adapter slot names
* a validation helper that asserts a registry satisfies all port contracts

No business-logic forks by provider live here — only parity rules.
"""

from __future__ import annotations

import inspect
from typing import Any, Dict, FrozenSet, Set, Type

from shared.adapters.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)

# ── Canonical profiles ──────────────────────────────────────────────
VALID_PROFILES: FrozenSet[str] = frozenset({"aws", "onprem"})

# ── Canonical adapter slots and their required port types ───────────
ADAPTER_SLOTS: Dict[str, Type[Any]] = {
    "object_storage": ObjectStoragePort,
    "queue": QueuePort,
    "eventing": EventingPort,
    "secrets": SecretsPort,
    "log_sink": LogSinkPort,
}


class ProfileValidationError(Exception):
    """Raised when a profile value or adapter registry is invalid."""


def validate_profile(profile: str) -> str:
    """Return *profile* lower-cased if valid, else raise."""
    normalized = profile.strip().lower()
    if normalized not in VALID_PROFILES:
        raise ProfileValidationError(
            f"Invalid DEPLOYMENT_PROFILE={profile!r}. "
            f"Must be one of {sorted(VALID_PROFILES)}."
        )
    return normalized


def validate_registry_parity(registry: Any) -> None:
    """Assert that *registry* exposes every adapter slot and that each
    returned adapter is an instance of the correct port type.

    This is intended for integration / smoke tests, not hot-path code.
    """
    missing_slots: list[str] = []
    wrong_types: list[str] = []

    for slot_name, port_type in ADAPTER_SLOTS.items():
        factory = getattr(registry, slot_name, None)
        if factory is None or not callable(factory):
            missing_slots.append(slot_name)
            continue
        try:
            instance = factory()
        except Exception as exc:  # noqa: BLE001
            wrong_types.append(f"{slot_name}: factory raised {exc!r}")
            continue
        if not isinstance(instance, port_type):
            wrong_types.append(
                f"{slot_name}: expected {port_type.__name__}, "
                f"got {type(instance).__name__}"
            )

    errors: list[str] = []
    if missing_slots:
        errors.append(f"Missing slots: {missing_slots}")
    if wrong_types:
        errors.append(f"Type mismatches: {wrong_types}")
    if errors:
        raise ProfileValidationError("; ".join(errors))


def validate_port_implementation(cls: Type[Any], port: Type[Any]) -> None:
    """Verify *cls* implements every abstract method declared by *port*.

    Raises ``ProfileValidationError`` on missing methods.
    """
    abstract_methods: Set[str] = set()
    for name, method in inspect.getmembers(port, predicate=inspect.isfunction):
        if getattr(method, "__isabstractmethod__", False):
            abstract_methods.add(name)

    missing = abstract_methods - {name for name, _ in inspect.getmembers(cls, predicate=inspect.isfunction)}
    if missing:
        raise ProfileValidationError(
            f"{cls.__name__} is missing implementations for "
            f"{port.__name__} methods: {sorted(missing)}"
        )

