"""
On-prem Redis-backed QueuePort adapter.

Uses a Redis list as a simple FIFO queue.
"""

from __future__ import annotations

import json
import os
import uuid
from typing import Any, Dict, Optional

import redis

from shared.adapters.ports import QueuePort


class RedisQueue(QueuePort):
    """Concrete Redis-list-backed queue."""

    def __init__(self) -> None:
        host = os.environ.get("REDIS_HOST", "localhost")
        port = int(os.environ.get("REDIS_PORT", "6379"))
        db = int(os.environ.get("REDIS_DB", "0"))
        password = os.environ.get("REDIS_PASSWORD")
        self._client = redis.Redis(host=host, port=port, db=db, password=password, decode_responses=True)

    def send_message(self, queue_name: str, body: str, attributes: Optional[Dict[str, str]] = None) -> str:
        message_id = str(uuid.uuid4())
        envelope = json.dumps({
            "message_id": message_id,
            "body": body,
            "attributes": attributes or {},
        })
        self._client.rpush(queue_name, envelope)
        return message_id

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[Dict[str, Any]]:
        results: list[Dict[str, Any]] = []
        for _ in range(max_messages):
            if wait_seconds > 0:
                item = self._client.blpop(queue_name, timeout=wait_seconds)
                raw = item[1] if item else None
            else:
                raw = self._client.lpop(queue_name)
            if raw is None:
                break
            envelope = json.loads(raw)
            results.append({
                "message_id": envelope["message_id"],
                "body": envelope["body"],
                "receipt_handle": envelope["message_id"],  # for Redis, receipt_handle == message_id
            })
        return results

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        # In this simple Redis-list model, messages are already removed on receive.
        # delete_message is a no-op for idempotency.
        pass

