"""
On-prem NATS EventingPort adapter.

Uses nats-py (async) wrapped in a sync helper for port parity.
"""

from __future__ import annotations

import json
import os
import uuid
from typing import Any, Dict

from shared.adapters.ports import EventingPort


class NatsEventing(EventingPort):
    """Concrete NATS-backed eventing.

    Uses synchronous ``nats-py`` client via ``asyncio.run`` for port
    interface parity.  For high-throughput production paths, a native
    async variant should be used.
    """

    def __init__(self) -> None:
        self._nats_url = os.environ.get("NATS_URL", "nats://localhost:4222")

    def publish(self, topic: str, event_type: str, payload: Dict[str, Any]) -> str:
        import asyncio
        import nats as nats_lib

        event_id = str(uuid.uuid4())
        message = json.dumps({
            "event_id": event_id,
            "event_type": event_type,
            "payload": payload,
        }).encode()

        async def _publish() -> None:
            nc = await nats_lib.connect(self._nats_url)
            try:
                await nc.publish(topic, message)
                await nc.flush()
            finally:
                await nc.close()

        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = None

        if loop and loop.is_running():
            import concurrent.futures
            with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
                pool.submit(asyncio.run, _publish()).result(timeout=10)
        else:
            asyncio.run(_publish())

        return event_id

