On-prem file-based LogSinkPort adapter.

Writes structured JSON log entries to a local file or stdout.
"""

from __future__ import annotations

import json
import os
import sys
import time
from typing import Any, Dict, TextIO


from shared.adapters.ports import LogSinkPort


class FileLogSink(LogSinkPort):
    """Concrete file/stdout log sink."""

    def __init__(self) -> None:
        log_path = os.environ.get("LOG_SINK_PATH")
        self._file_handle: TextIO | None = None
        if log_path:
            os.makedirs(os.path.dirname(log_path) or ".", exist_ok=True)
            self._file_handle = open(log_path, "a", encoding="utf-8")  # noqa: SIM115

    def emit(self, log_entry: Dict[str, Any]) -> None:
        entry = {
            "timestamp": time.time(),
            **log_entry,
        }
        line = json.dumps(entry)
        if self._file_handle:
            self._file_handle.write(line + "\n")
            self._file_handle.flush()
        else:
            print(line, file=sys.stderr)

