class TestAwsObjectStorageIntegration:
    """Store and retrieve an object via S3 adapter against LocalStack.

    Requires:
        - LocalStack running on localhost:4566
        - AWS_ENDPOINT_URL=http://localhost:4566
        - DEPLOYMENT_PROFILE=aws
    """

    @pytest.fixture(autouse=True)
    def _setup_env(self) -> Generator[None, None, None]:
        env = {
            "DEPLOYMENT_PROFILE": "aws",
            "AWS_ENDPOINT_URL": os.environ.get("AWS_ENDPOINT_URL", "http://localhost:4566"),
            "AWS_ACCESS_KEY_ID": os.environ.get("AWS_ACCESS_KEY_ID", "test"),
            "AWS_SECRET_ACCESS_KEY": os.environ.get("AWS_SECRET_ACCESS_KEY", "test"),
            "AWS_DEFAULT_REGION": "us-east-1",
        }
        with patch.dict(os.environ, env, clear=False):
            get_registry.cache_clear()
            yield
        get_registry.cache_clear()

    def test_put_and_get_object(self) -> None:
        registry = AdapterRegistry(profile="aws")
        storage = registry.object_storage()
        bucket = f"test-bucket-{uuid.uuid4().hex[:8]}"
        key = "test-key.txt"
        data = b"hello from aws integration test"

        storage.put_object(bucket, key, data)
        retrieved = storage.get_object(bucket, key)
        assert retrieved == data

    def test_get_nonexistent_raises_key_error(self) -> None:
        registry = AdapterRegistry(profile="aws")
        storage = registry.object_storage()
        bucket = f"test-bucket-{uuid.uuid4().hex[:8]}"
        with pytest.raises(KeyError):
            storage.get_object(bucket, "nonexistent-key")

    def test_delete_is_idempotent(self) -> None:
        registry = AdapterRegistry(profile="aws")
        storage = registry.object_storage()
        bucket = f"test-bucket-{uuid.uuid4().hex[:8]}"
        # Should not raise even if bucket/key don't exist
        storage.delete_object(bucket, "nonexistent-key")

    def test_list_objects(self) -> None:
        registry = AdapterRegistry(profile="aws")
        storage = registry.object_storage()
        bucket = f"test-bucket-{uuid.uuid4().hex[:8]}"
