            with patch.dict(os.environ, env_onprem, clear=False):
                onprem_adapter = getattr(onprem_reg, slot_name)()
            assert isinstance(aws_adapter, port_type), f"aws.{slot_name} not {port_type.__name__}"
            assert isinstance(onprem_adapter, port_type), f"onprem.{slot_name} not {port_type.__name__}"


