def _adapter_env(profile: str) -> dict[str, str]:
    """Return minimal env vars so adapters can be constructed without
    actually connecting to external services (for type-check tests)."""
    base = {"DEPLOYMENT_PROFILE": profile}
    if profile == "aws":
        base.update({
            "AWS_ENDPOINT_URL": os.environ.get("AWS_ENDPOINT_URL", "http://localhost:4566"),
            "AWS_ACCESS_KEY_ID": os.environ.get("AWS_ACCESS_KEY_ID", "test"),
            "AWS_SECRET_ACCESS_KEY": os.environ.get("AWS_SECRET_ACCESS_KEY", "test"),
            "AWS_DEFAULT_REGION": "us-east-1",
        })
    else:
        base.update({
            "MINIO_ENDPOINT_URL": os.environ.get("MINIO_ENDPOINT_URL", "http://localhost:9000"),
            "MINIO_ACCESS_KEY": "minioadmin",
            "MINIO_SECRET_KEY": "minioadmin",
            "REDIS_HOST": "localhost",
            "NATS_URL": "nats://localhost:4222",
            "VAULT_ADDR": "http://localhost:8200",
            "VAULT_TOKEN": "root",
        })
    return base

